/**
 * Generates src/contract.gen.ts, the TypeScript types of the Smarter Chat api contract, from
 * contract/chat-contract.schema.json.
 *
 * The schema is generated by the Smarter backend, from the contract's Pydantic models
 * (smarter.apps.prompt.contract.models), and copied here by `make chat-contract` in the Smarter
 * repository. src/contract.test.ts fails if src/contract.gen.ts is out of date.
 *
 *     npm run contract:types          # writes src/contract.gen.ts
 *     node scripts/contract-types.mjs --check  # exits 1 if src/contract.gen.ts is out of date
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const SCHEMA_PATH = path.join(root, "contract", "chat-contract.schema.json");
export const TYPES_PATH = path.join(root, "src", "contract.gen.ts");

const BANNER = `/**
 * The Smarter Chat api contract: generated from contract/chat-contract.schema.json by
 * scripts/contract-types.mjs. Do not edit; run \`npm run contract:types\`.
 */`;

/**
 * The schema without the titles of its fields, which Pydantic adds to every field, and which
 * json-schema-to-typescript would otherwise turn into a named type each (AppName, AppName1, ...).
 * The titles of the definitions, which are the models' names, are kept.
 */
function withoutFieldTitles(node, isDefinition = false) {
  if (Array.isArray(node)) return node.map((item) => withoutFieldTitles(item));
  if (!node || typeof node !== "object") return node;
  const result = {};
  for (const [key, value] of Object.entries(node)) {
    if (key === "title" && !isDefinition) continue;
    if (key === "$defs") {
      result[key] = Object.fromEntries(
        Object.entries(value).map(([name, def]) => [name, withoutFieldTitles(def, true)]),
      );
    } else {
      result[key] = withoutFieldTitles(value);
    }
  }
  return result;
}

/** The generated TypeScript source. */
export async function contractTypes() {
  const schema = withoutFieldTitles(JSON.parse(fs.readFileSync(SCHEMA_PATH, "utf-8")), true);
  return compile(schema, "SmarterChatApiContract", {
    bannerComment: BANNER,
    unreachableDefinitions: true,
    additionalProperties: true,
    style: { printWidth: 120, trailingComma: "all" },
  });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const types = await contractTypes();
  if (process.argv.includes("--check")) {
    const current = fs.existsSync(TYPES_PATH) ? fs.readFileSync(TYPES_PATH, "utf-8") : "";
    if (current !== types) {
      console.error(`${path.relative(root, TYPES_PATH)} is out of date. Run \`npm run contract:types\`.`);
      process.exit(1);
    }
  } else {
    fs.writeFileSync(TYPES_PATH, types);
    console.log(`wrote ${path.relative(root, TYPES_PATH)}`);
  }
}
